mapper.select:
select t.create_staff_name,t.create_staff_name createStaffName,t.pqs_id,t.pqs_id
pqsId,t.expired,t.create_staff_id,t.create_staff_id createStaffId,t.audit,t.status_cd,t.status_cd
statusCd,t.remark,t.state,t.qrcode_name,t.qrcode_name qrcodeName,t.community_id,t.community_id
communityId,t.sms_validate,t.sms_validate smsValidate,t.create_time createTime
from pass_qrcode_setting t
where 1 =1

    and t.create_staff_name= #{createStaffName}


    and t.pqs_id= #{pqsId}


    and t.expired= #{expired}


    and t.create_staff_id= #{createStaffId}


    and t.audit= #{audit}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.state= #{state}


    and t.qrcode_name= #{qrcodeName}


    and t.community_id= #{communityId}


    and t.sms_validate= #{smsValidate}

order by t.create_time desc

    limit #{page}, #{row}

